import React from 'react';
// Assuming Tailwind CSS is set up in your project
// Assuming you are using React Router for <Link /> components
// import { Link } from 'react-router-dom'; // Uncomment this if using React Router

// Placeholder Link component if React Router is not set up
// Replace with actual Link import if using React Router
const Link = ({ to, children, ...props }) => <a href={to} {...props}>{children}</a>;

function Navbar() {
  return (
    // Navigation Bar container
    // Uses Tailwind classes for styling, responsiveness, and shadow
    // Note: Dark mode classes are NOT included in this component
    <nav className="w-full bg-white shadow-md p-4 flex justify-between items-center">
      {/* Site Title/Logo - Links to the homepage */}
      {/* Uses Tailwind classes for text styling and hover effects */}
      <Link to="/" className="text-xl font-bold text-blue-600 hover:text-blue-800 transition-colors duration-200">
        FB Downloader
      </Link>

      {/* Navigation Links */}
      {/* Flex container for links, with spacing */}
      <div className="flex items-center space-x-4">
        {/* Example Nav Link - How It Works */}
        {/* Replace '/how-it-works' with the actual path */}
        {/* Uses Tailwind classes for text styling and hover effects */}
        {/*
        <Link to="/how-it-works" className="text-gray-700 hover:text-blue-600 transition-colors duration-200">
          How It Works
        </Link>
        */}

        {/* Example Nav Link - FAQ */}
        {/* Replace '/faq' with the actual path */}
        {/*
        <Link to="/faq" className="text-gray-700 hover:text-blue-600 transition-colors duration-200">
          FAQ
        </Link>
        */}

        {/*
          Add more navigation links here as needed.
          For example:
          <Link to="/contact" className="text-gray-700 hover:text-blue-600 transition-colors duration-200">
            Contact
          </Link>
        */}

        {/*
          The Dark Mode Toggle button should be handled in the parent component (e.g., App.js)
          if you want it to control the theme of the entire page.
          It is not included in this Navbar component as requested.
        */}

      </div>
    </nav>
  );
}

export default Navbar;
